/// The number spec for `lang` in numbering system `ns`, following UTS #35
/// resource inheritance: the locale's own `symbols-numberSystem-<ns>`
/// block, else root's for that system, else the locale's `latn` block.
/// Missing the middle step is what would make `en-u-nu-arab` group with a
/// comma instead of U+066C.
pub(crate) fn spec(lang: &str, ns: &str) -> Option<NumberSpec> {
    let i = locale_index(lang)?;
    if let Some(s) = other(i, ns) {
        return Some(s);
    }
    let l = latn(i)?;
    if let Some(s) = root(i, ns, l) {
        return Some(s);
    }
    Some(l)
}

