/// Root's `symbols-numberSystem-<ns>` block, for a locale that ships none
/// of its own; `i`/`latn` are the requesting locale's table index and
/// `latn` spec, which root's format aliases (`alias source=locale`)
/// resolve against. Follows `number-numsys` with the per-locale blocks:
/// without it a `-u-nu-` request keeps the requesting locale's
/// separators throughout.
fn root(i: u16, ns: &str, latn: NumberSpec) -> Option<NumberSpec> {
    let _ = (i, &latn);
    Some(match ns {
        #[cfg(feature = "number-numsys")]
        "arab" => NumberSpec {
            decimal: "٫",
            group: "٬",
            minus: "\u{61c}-",
            plus: "\u{61c}+",
            percent: "٪\u{61c}",
            nan: "NaN",
            infinity: "∞",
            exponential: "اس",
            min_grouping: latn.min_grouping,
            dec: latn.dec,
            pct: Pattern {
                prefix: "",
                suffix: "٪\u{61c}",
                min_int: 1,
                min_frac: 0,
                max_frac: 0,
                primary_group: 3,
                secondary_group: 3,
            },
        },
        #[cfg(feature = "number-numsys")]
        "arabext" => NumberSpec {
            decimal: "٫",
            group: "٬",
            minus: "\u{200e}-\u{200e}",
            plus: "\u{200e}+\u{200e}",
            percent: "٪",
            nan: "NaN",
            infinity: "∞",
            exponential: "×۱۰^",
            min_grouping: latn.min_grouping,
            dec: latn.dec,
            pct: root_pct(i, "arabext").unwrap_or(latn.pct),
        },
        _ => return None,
    })
}

