/// Locales that inherit another's symbols but not its numbering systems:
/// CLDR's region files override `defaultNumberingSystem` alone, so the
/// override cannot be keyed by the shared table index.
fn region_numbering_systems(lang: &str) -> Option<(&'static str, &'static str)> {
    Some(match lang {
        "ar-lb" | "ar-mr" => ("arab", "arab"),
        _ => return None,
    })
}

